import json


def append_operations_guide(doc, root, add_table, add_code_block):
    report = json.loads((root / 'reports/local_operations.json').read_text(encoding='utf-8'))
    deployment = report['deployment']
    doc.add_page_break()
    doc.add_heading('Автоматические проверки развёртывание и мониторинг', level=1)
    doc.add_paragraph('Подготовлен локальный эксплуатационный стенд: API за HTTPS reverse proxy, параллельный HTTP benchmark, Prometheus и Grafana. GitHub Actions выполняет тесты и review ноутбуки на Windows и Linux, а отдельный Linux job собирает контейнер и проверяет полный стенд. Эти результаты относятся к демонстрационной базе знаний. Экспертной банковской приёмки и внешнего production развёртывания пока нет. По решению владельца проект готовится локально без сервера и домена.')
    doc.add_heading('Какие проблемы решает этот этап', level=2)
    doc.add_paragraph('Локально работающая функция ещё не гарантирует повторяемую сборку, корректный доступ через HTTPS и наблюдаемость отказов. CI проверяет изменения в чистом окружении. Нагрузочный клиент показывает поведение нескольких одновременных обращений. Метрики позволяют различать нормальные ответы, ошибки авторизации, лимиты и недоступность компонентов. Каждый вид проверки отвечает на свой вопрос и не заменяет оценку релевантности или правильности банковского ответа.')
    doc.add_heading('Как устроен CI', level=2)
    doc.add_paragraph('Workflow .github/workflows/checks.yaml запускается при push, pull_request и ручном запуске. Права GITHUB_TOKEN ограничены contents:read. Actions закреплены по commit SHA. Есть таймауты jobs и отмена устаревшего запуска той же ветки. Документальные обновления Word и итогового эксплуатационного отчёта исключены из автоматического повторного запуска; изменения кода, тестов, конфигураций и ноутбуков проверки запускают.')
    doc.add_paragraph('Матрица Windows/Linux использует Python 3.14, устанавливает requirements-validation, выполняет check_project.py и ноутбуки 09, 10, 11. Эти ноутбуки не обучают классификатор на official test и не расходуют банковский holdout. Контейнерный job отдельно собирает Docker image и вызывает verify_local_deployment.py --monitoring. Артефакты тестов и обезличенный эксплуатационный отчёт сохраняются на 14 дней. Секретные файлы находятся за пределами каталога загружаемых артефактов и удаляются при завершении проверки.')
    ci = report['ci']
    doc.add_paragraph(f"Зафиксированный CI: {ci['url']}. Commit: {ci['head_sha']}. Статус: {ci['conclusion']}. Локально пройдены {report['automated_tests']} тестов. Данные отчёта и точные результаты контейнерной проверки сохранены в reports/local_operations.json; отчёт относится к указанному commit и среде GitHub runner.")
    doc.add_paragraph('Первый Windows job прошёл тесты, но упал при печати русского сообщения после выполнения ноутбука: системная cp1252 не кодировала кириллицу. Это была ошибка переносимости служебного вывода. Строка progress заменена на ASCII, для workflow включён PYTHONUTF8=1. Исправление проверяется фактическим повторным запуском. Ошибка сохранена в истории CI, а не скрыта утверждением, что первый запуск сразу был зелёным.')
    doc.add_heading('Локальная схема HTTPS', level=2)
    add_table(doc, ['Компонент', 'Роль', 'Доступ'], [
        ('Caddy', 'TLS termination и reverse proxy к API', 'https localhost порт 8443 только loopback'),
        ('Support API', 'Lexical demo поиск и ответы с цитатами', 'Внутренняя Compose сеть без опубликованного API порта'),
        ('Prometheus', 'Scrape защищённых метрик и evaluation правил', '127.0.0.1 порт 9090'),
        ('Grafana', 'Provisioned dashboard с Prometheus datasource', '127.0.0.1 порт 3000 с паролем администратора')])
    doc.add_paragraph('Caddy использует локальный CA. Клиент явно получает root.crt и проверяет сертификат и имя localhost. Без этого CA соединение должно завершаться ошибкой доверия. Проверка не отключает TLS verification и не добавляет сертификаты в системное хранилище Windows. Браузер без настройки доверия покажет предупреждение. Для внешнего домена потребуется отдельная конфигурация публичного TLS и правил доступа; текущие loopback настройки не являются внешним развёртыванием.')
    doc.add_paragraph('API работает как appuser с read-only root filesystem, сброшенными capabilities и ограничениями CPU/RAM. Документационные пути скрыты на gateway. API key требуется для /v1 и обоих endpoints метрик. Это простой доступ для локального стенда; пользовательские роли, SSO и распределённая аутентификация этим не реализованы. Grafana и Prometheus доступны на локальном интерфейсе, что не означает разрешение публиковать их открытыми в интернет.')
    doc.add_heading('Как запускать и останавливать', level=2)
    add_code_block(doc, '''docker build -t x20-support-api:latest .
python scripts/manage_local_stack.py up --monitoring
python scripts/manage_local_stack.py status
python scripts/manage_local_stack.py down''')
    doc.add_paragraph('Для API без мониторинга используйте up без --monitoring при первом создании профиля. Настройки существующего профиля сохраняются. Ключ API и пароль Grafana генерируются в ignored work/local_stack, их значения не печатаются. Имя пользователя Grafana — admin. Команда down сохраняет volumes мониторинга. Проверочный скрипт использует отдельный случайный project и в конце удаляет только свои containers, volumes и временные секреты. Обученный классификатор в этот минимальный стенд не монтируется; его readiness ожидаемо равна нулю.')
    add_code_block(doc, '''python scripts/verify_local_deployment.py --monitoring
python scripts/load_http.py --url https://localhost:8443 --ca work/local_stack/root.crt --requests 120 --concurrency 4 --output work/load_profile.json''')
    doc.add_paragraph('Для отдельного нагрузочного клиента SUPPORT_API_KEY задаётся через окружение из локального секретного файла. Не вставляйте ключ в команды с литералом или в ячейки ноутбука. Клиент ограничен HTTPS origin localhost и не отправляет тестовую нагрузку внешним адресатам. Соединение идёт на IPv4 loopback с TLS server name localhost и без системного proxy. Это устраняет не относящийся к серверу IPv6 fallback и сохраняет проверку имени сертификата.')
    doc.add_heading('Что измеряет нагрузочная проверка', level=2)
    doc.add_paragraph('Профили используют только демонстрационные calibration запросы. При 1, 4 и 12 workers выполняется по 120 запросов, дополнительно 10 секунд работают 8 workers. Это closed-loop: каждый worker ждёт ответ перед следующим обращением. Каждое обращение создаёт новое HTTPS соединение. Клиентские P50, P95 и P99 включают установление TLS, сетевой обмен и чтение JSON. Скорость завершённых запросов не равна гарантированной пропускной способности при любом внешнем потоке.')
    add_table(doc, ['Workers', 'Запросы', 'Успех', 'P95 мс', 'Запросов в секунду'], [
        (str(row['concurrency']), str(row['request_count']), f"{row['success_rate']:.0%}", f"{row['p95_ms']:.2f}", f"{row['completed_requests_per_second']:.2f}")
        for row in deployment['search_profiles']])
    limited = deployment['rate_limit_profile']
    doc.add_paragraph(f"Отдельная фаза после пересоздания API использует лимит 20 запросов в минуту и 60 параллельно запланированных обращений. Получены статусы {limited['status_counts']}. Здесь 429 ожидаемы и подтверждают ограничение. В профиле успешного поиска такие ответы считались бы отказами. Лимит общий для одного process и использует фиксированное окно, поэтому не является распределённым per-user лимитом и допускает особенности на границе минут.")
    doc.add_paragraph('Десятисекундный профиль не подтверждает суточную устойчивость, восстановление после отказа узла или SLA. Benchmark не нагружает Ollama, агента и классификатор. Эти компоненты требуют отдельных профилей с длиной запросов, очередями, budget и контролем памяти. Показатели GitHub runner нельзя переносить на ноутбук пользователя или будущий сервер без повторного замера.')
    doc.add_heading('Метрики и исправленный пропуск отказов', level=2)
    doc.add_paragraph('До этого этапа middleware возвращал 401 и 429 раньше обновления счётчиков. В результате именно отказы контроля доступа и лимита не попадали в наблюдаемость. Учёт перенесён в общий finally блок. Теперь учитываются ранние ответы, штатные статусы и исключения обработки; response получает nosniff, для 429 сохраняется Retry-After. Тесты и контейнерная проверка подтверждают наличие отказов в метриках.')
    doc.add_paragraph('JSON endpoint /metrics сохранён. Добавлен /metrics/prometheus: счётчик запросов, сумма и количество серверных длительностей, cumulative histogram buckets и gauges наличия индекса и модели. В labels используются method, route и status, без текстов вопросов и API key. Неизвестные пути объединяются в unmatched. Время измеряется до возврата response из middleware; оно не включает полное чтение ответа клиентом. Prometheus P95 по buckets приближённый и отличается от percentile полного списка клиентских измерений.')
    doc.add_heading('Дашборд и правила оповещений', level=2)
    doc.add_paragraph('Grafana получает datasource и dashboard из файлов provisioning. Панели показывают requests per second, серверный histogram P95, отказы 401/429 и readiness. Prometheus читает x-api-key из отдельного секретного файла. Четыре правила проверяют недоступность scrape target, отсутствие индекса, повышенную долю 5xx и частые 429. Тест подтверждает доступность target и загрузку dashboard и правил. Доставка уведомлений через Alertmanager, email или мессенджеры не настроена; сообщения никому не отправляются. Пороговые значения правил исследовательские и должны согласовываться с эксплуатацией.')
    doc.add_heading('Сбой диска и восстановление среды', level=2)
    doc.add_paragraph('При первом локальном скачивании Grafana на C осталось около 6 МБ. Docker вернул input/output error; неполный нагрузочный прогон остановлен и не представлен успешным. Были удалены временные изображения визуальной проверки Word, кеш ранее исключённого cross-encoder и неиспользуемая копия Python пакетов в work/python-deps. Перед удалением проверено, что рабочие импорты идут из основного Python, а ссылок на временную копию в проекте нет. Исходники, документы и обученные модели сохранены.')
    doc.add_paragraph('После освобождения места зависший Docker восстановлен, временные контейнеры прерванной проверки удалены. Полный monitoring запуск теперь требует минимум 4 GiB свободного места; bare API менеджер требует 1 GiB. Это нижний preflight порог, а не обещание достаточного места для любого набора образов и данных. Стенд с мониторингом проверен на Linux runner, локальный HTTPS поиск повторяется отдельно без тяжёлых загрузок. Перед постоянным запуском на пользовательском компьютере нужно дополнительно освободить место.')
    doc.add_heading('Что ещё требуется до банковской эксплуатации', level=2)
    doc.add_paragraph('Остаются экспертная проверка источников, независимые вопросы, калибровка и новый holdout на банковском корпусе, затем оценка действий и ответов агента. Внешний сервер и домен пока не выбраны. Отдельно нужны длительные и LLM нагрузочные проверки, согласованные SLO, политика секретов и ролей, доставка оповещений, резервное копирование с проверкой восстановления и процесс одобренного обновления корпуса. CI и локальный мониторинг не заменяют эти решения.')
    doc.add_heading('Вопросы для собеседования об эксплуатации', level=2)
    for question, answer in [
        ('Почему зелёные unit tests не заменяют контейнерную проверку', 'Unit tests могут подменять зависимости. Отдельный job проверяет сборку, сеть, TLS, секреты, права файлов и provisioning работающих сервисов.'),
        ('Почему нужно считать 401 и 429', 'Иначе мониторинг скрывает ошибки доступа и перегрузку. Ожидаемый отказ может быть правильным поведением системы и всё равно должен учитываться.'),
        ('Почему средняя задержка недостаточна', 'Среднее скрывает хвост распределения. P95 и P99 показывают медленные ответы, но требуют указания профиля нагрузки и объёма измерений.'),
        ('Зачем CA передаётся явно', 'Клиент проверяет подлинность локального сервера без отключения TLS verification и без изменения системного доверия на машине пользователя.'),
        ('Что доказывает наличие alert rules', 'Правила загружены и могут вычисляться. Это ещё не подтверждает доставку сообщения человеку или согласованный процесс реагирования на инцидент.')]:
        doc.add_paragraph(question, style='Heading 3')
        doc.add_paragraph(answer)
    doc.add_paragraph('Первичные справочные материалы: https://docs.github.com/en/actions/tutorials/build-and-test-code/python ; https://caddyserver.com/docs/automatic-https ; https://prometheus.io/docs/prometheus/latest/configuration/ ; https://grafana.com/docs/grafana/latest/administration/provisioning/ . Фактические результаты и ограничения проекта приведены в reports/local_operations.json.')
